HarnessSpend = typing.TypedDict("HarnessSpend", {
    "harness": "str",
    "vendor": "str",
    "account_id": "str",
})

# LauncherAccount is an account one of a machine's launchers is signed in to.
LauncherAccount = typing.TypedDict("LauncherAccount", {
    "vendor": "str",
    "account_id": "str",
    "unrouted": "typing.NotRequired[bool]",
})

# LauncherNoAccount is a launcher of the machine's that offers no account, with its one cause as
